<?php get_header();while(have_posts()):the_post();$c=get_the_category();?><main id="main" class="canvas single-post"><article><header class="article-head"><p class="eyebrow">LOG / <?php echo esc_html($c?$c[0]->name:'JOURNAL');?> / <?php echo esc_html(get_the_date('Y.m.d'));?></p><h1><?php the_title();?></h1><?php if(has_excerpt()):?><p class="lead"><?php echo esc_html(get_the_excerpt());?></p><?php endif;?></header><div class="article-content"><?php the_content();?></div></article></main><?php endwhile;get_footer();?>